import{_ as a,c as t,o,ag as r}from"./chunks/framework._xRlcm3f.js";const I=JSON.parse('{"title":"人工智能","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ai.md","filePath":"guide/ai.md","lastUpdated":1790228279000}'),i={name:"guide/ai.md"};function l(n,e,d,s,c,A){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="人工智能" tabindex="-1">人工智能 <a class="header-anchor" href="#人工智能" aria-label="Permalink to &quot;人工智能&quot;">​</a></h1><p>插件集成 AI 能力，用于辅助写作、标题/摘要生成等。需要在「偏好设置」中启用并填写体验码/模型配置。</p><h2 id="入口" tabindex="-1">入口 <a class="header-anchor" href="#入口" aria-label="Permalink to &quot;入口&quot;">​</a></h2><ul><li>入口：设置 → <strong>AI 设置</strong> 启用 AI；面板头部 <strong>AI 图标</strong> 打开 AI 对话。</li><li>菜单：偏好设置中「显示 AI 菜单」开关控制 AI 入口是否显示。</li></ul><h2 id="配置项" tabindex="-1">配置项 <a class="header-anchor" href="#配置项" aria-label="Permalink to &quot;配置项&quot;">​</a></h2><ul><li><strong>启用 AI</strong>（<code>experimentalAIEnabled</code>）：总开关。</li><li><strong>AI 体验码 / 模型</strong>（<code>experimentalAICode</code>、<code>experimentalAIApiModel</code>）：接入模型。</li><li><strong>AI 基础地址</strong>（<code>experimentalAIBaseUrl</code>）：API 地址。</li><li><strong>AI 代理地址</strong>（<code>experimentalAIProxyUrl</code>）：有代理时配置。</li><li><strong>AI token 数目</strong>（<code>experimentalAIApiMaxTokens</code>）：单次生成上限。</li><li><strong>AI 温度</strong>（<code>experimentalAIApiTemperature</code>）：采样温度。</li></ul><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><ul><li>AI 配置为实验性能力，具体接入的模型/服务以可用的 API 为准。</li><li>相关字段与行为变更请以插件发布说明为准。</li></ul>',8)])])}const u=a(i,[["render",l]]);export{I as __pageData,u as default};
